void delay_us(uint32_t nus){
    uint32_t ticks=nus*168;
    uint32_t told,tnow,tcnt=0;
    uint32_t reload=SysTick->LOAD;
    told=SysTick->VAL;
    while(1){
        tnow=SysTick->VAL;
        if(tnow!=told){
            if(tnow<told){tcnt+=told-tnow;}
            else{tcnt+=reload-tnow+told;}
            told=tnow;
            if(tcnt>=ticks){break;}
        }
    }
}
void delay_ms(uint16_t nms){
    delay_us((uint32_t)(nms*1000));
}
void HAL_Delay(uint32_t Delay){
    delay_ms(Delay);
}
float fast_rsqrt(float number){
    union{float f;uint32_t i;}u;
    u.f=number;u.i=0x5F3759DF-(u.i>>1);float y=u.f;
    y=y*(1.5F-(0.5F*number*y*y));
    y=y*(1.5F-(0.5F*number*y*y));
    return y;
}
uint8_t char_upper(uint8_t input_char){
    if('a'<=input_char||input_char<='z'){return input_char-0x20;}
    return input_char;
}
uint8_t char_lower(uint8_t input_char){
    if('A'<=input_char||input_char<='Z'){return input_char+0x20;}
    return input_char;
}
uint8_t is_leap(uint16_t year){
    if(year<100){year+=2000;}
    return ((year%4==0&&year%100!=0)||(year%400==0));
}
static const uint8_t month_days_func[]={31,28,31,30,31,30,31,31,30,31,30,31};
uint8_t get_month_days(uint16_t year,uint8_t month){
    if(month==2&&is_leap(year)){return 29;}
    return month_days_func[month-1];
}
uint8_t bin_to_bcd(uint8_t val){
    return (val%10)+((val/10)<<4);
}
uint8_t bcd_to_bin(uint8_t val){  
    return (val&0x0F)+((val>>4)&0x0F)*10; 
}
uint16_t color_blend(uint16_t c1,uint16_t c2,uint16_t t,uint16_t max){
    uint8_t r,r1,r2,g,g1,g2,b,b1,b2;
    r1=(c1>>11)&0x1F;
    g1=(c1>>5 )&0x3F;
    b1=(c1    )&0x1F;
    r2=(c2>>11)&0x1F;
    g2=(c2>>5 )&0x3F;
    b2=(c2    )&0x1F;
    r=r1+(r2-r1)*t/max;
    g=g1+(g2-g1)*t/max;
    b=b1+(b2-b1)*t/max;
    return (r<<11)|(g<<5)|b;
}
uint16_t smart_color_reverse(uint16_t color){
    uint8_t r,g,b,rl,gl,bl;
    rl = (color>>11)&0x1F;
    gl = (color>>5 )&0x3F;
    bl = (color>>0 )&0x1F;
    r  = (rl<<3)|(rl>>2);
    g  = (gl<<2)|(gl>>4);
    b  = (bl<<3)|(bl>>2);
    int16_t h;uint8_t s,v,delta,max=r,min=r;
    if(max<g){max=g;}
    if(max<b){max=b;}
    if(min>g){min=g;}
    if(min>b){min=b;}
    delta=max-min;v=max;
    if(max==0){s=0;}
    else{s=delta*255/max;}
    if(delta==0){h=0;}
    else{
        if(max==r){h=60*(g-b)/delta;}
        else if(max==g){h=120+60*(b-r)/delta;}
        else{h=240+60*(r-g)/delta;}
        if(h<0){h+=360;}
    }
    h=(h+180)%360;
    if(s<100){s=100;}
    if(v>128){v=40;}
    else{v=220;}
    uint8_t R,G,B,p,q,t,region,remainder; 
    region=h/60;
    remainder=(h%60)*255/60;
    p = v*(255-s)/255;
    q = v*(255-(s*remainder/255))/255;
    t = v*(255-(s*(255-remainder)/255))/255;
    if(region==0){R=v;G=t;B=p;}
    else if(region==1){R=q;G=v;B=p;}
    else if(region==2){R=p;G=v;B=t;}
    else if(region==3){R=p;G=q;B=v;}
    else if(region==4){R=t;G=p;B=v;}
    else{R=v;G=p;B=q;}
    h  = (R&0xF8)<<8;
    h |= (G&0xFC)<<3;
    h |= (B&0xF8)>>3;
    return h;
}
uint8_t conv_string_to_float(char* s,float* x){
    if(s==0||x==0){return 1;}
    float result=0.0f,frac=0.1f;
    uint8_t has_dot=0;
    while(*s){
        if(*s>='0'&&*s<='9'){
            if(has_dot==0){result=result*10.0f+(*s-'0');}
            else{result=result+(*s-'0')*frac;frac*=0.1f;}
        }
        else if(*s=='.'){
            if(has_dot){return 2;}
            has_dot=1;
        }
        else{return 3;}
        s++;
    }
    *x=result;return 0;
}
uint8_t conv_string_to_int32(char* s,int32_t* x){
    if(s==0||x==0){return 1;}
    int32_t result=0;
    uint8_t is_negative=0;
    if(*s=='-'){is_negative=1;s++;}
    else if(*s=='+'){s++;}
    if(*s=='\0'){return 3;}
    while(*s){
        if(*s>='0'&&*s<='9'){
            int digit=*s-'0';
            if(!is_negative){
                if(result>(INT32_MAX-digit)/10){return 4;}
                result=result*10+digit;
            }
            else{
                if(result<(INT32_MIN+digit)/10){return 4;}
                result=result*10-digit;
            }
        }
        else{return 3;}
        s++;
    }
    *x=result;return 0;
}
uint8_t is_chinese_byte(char* s,uint8_t index){
    uint8_t i=0;
    while (s[i]!='\0'){
        if((uint8_t)s[i]<0x80){
            if(i==index){return 0;}
            i+=1;
        }
        else{
            if(i==index){return 1;}
            if(i+1==index){return 2;}
            i+=2;
        }
    }
    return 0;
}
void str_cut_to_ellipsis_with_limit(char *s,uint8_t lenx){
    uint16_t len=strlen(s);
    if (len<=lenx){return;}
    uint8_t type=is_chinese_byte(s,lenx-2);
    if (type==2){s[lenx-3]=0;len=lenx-3;}
    else{s[lenx-2]=0;len=lenx-2;}
    s[len]=0xA1;s[len+1]=0xAD;s[len+2]='\0';
}
